/// The matcha theme.
pub fn theme() -> Theme {
    Theme {
        name: Cow::Borrowed("matcha"),
        light: LIGHT,
        dark: DARK,
        components: Cow::Borrowed(COMPONENTS),
        adaptations: Cow::Borrowed(ADAPTATIONS),
        width_breakpoints: WIDTH_BREAKPOINTS,
        on_dark: ON_DARK,
        on_light: ON_LIGHT,
        icons: Cow::Borrowed(ICONS),
        fonts: Cow::Borrowed(FONTS),
        motion_tempo: 1.0,
    }
}
